package com.smartparking.dao;
import com.smartparking.database.DBConnection;import com.smartparking.model.*;import java.sql.*;import java.util.*;
public class VehicleDAO { public void save(Vehicle v) throws SQLException {try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement("INSERT INTO vehicles(registration_number,owner_name,vehicle_type) VALUES(?,?,?)")){p.setString(1,v.getRegistrationNumber());p.setString(2,v.getOwnerName());p.setString(3,v.getType());p.executeUpdate();}} public Optional<Vehicle> find(String r)throws SQLException{try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement("SELECT * FROM vehicles WHERE registration_number=?")){p.setString(1,r);try(ResultSet x=p.executeQuery()){return x.next()?Optional.of(map(x)):Optional.empty();}}} public List<Vehicle> all()throws SQLException{try(Connection c=DBConnection.open();PreparedStatement p=c.prepareStatement("SELECT * FROM vehicles ORDER BY registration_number");ResultSet x=p.executeQuery()){List<Vehicle>out=new ArrayList<>();while(x.next())out.add(map(x));return out;}} private Vehicle map(ResultSet r)throws SQLException{return switch(r.getString("vehicle_type")){case "CAR"->new Car(r.getString("registration_number"),r.getString("owner_name"));case "BIKE"->new Bike(r.getString("registration_number"),r.getString("owner_name"));default->new Truck(r.getString("registration_number"),r.getString("owner_name"));};} }
